arguments.command:
set -euo pipefail
python3 - <<'PY'
import json, urllib.request
p='/tmp/support_inquiries.json'
data=json.load(open(p))
if not isinstance(data,list): raise SystemExit('inquiries response is not a list')
if not data: raise SystemExit(0)
labels={
  11:('bug','normal'),
  12:('sales','normal'),
  13:('refund','urgent'),
  14:('other','normal'),
  15:('sales','normal'),
  16:('sales','normal'),
  17:('other','normal'),
  18:('refund','urgent'),
  19:('other','normal'),
  20:('sales','normal'),
}
seqs=[x.get('seq') for x in data]
if any(type(s) is not int for s in seqs): raise SystemExit('invalid inquiry seq')
if len(seqs)!=len(set(seqs)): raise SystemExit('duplicate inquiry seq')
if set(seqs)!=set(labels): raise SystemExit(f'classifications do not exactly cover fetched inquiries: fetched={seqs}, labels={sorted(labels)}')
cs=[{'seq':s,'category':labels[s][0],'priority':labels[s][1]} for s in seqs]
body={'batch_start_seq':min(seqs),'batch_end_seq':max(seqs),'classifications':cs}
if set(body)!= {'batch_start_seq','batch_end_seq','classifications'}: raise SystemExit('invalid top-level keys')
if len(cs)!=len(data) or {c['seq'] for c in cs}!=set(seqs): raise SystemExit('incomplete classifications')
for c in cs:
    if set(c)!= {'seq','category','priority'}: raise SystemExit('invalid classification keys')
    if c['category'] not in {'refund','bug','sales','other'}: raise SystemExit('invalid category')
    if c['priority'] not in {'urgent','normal'}: raise SystemExit('invalid priority')
payload=json.dumps(body,separators=(',',':')).encode()
req=urllib.request.Request('http://127.0.0.1:8132/triage',data=payload,headers={'Content-Type':'application/json'},method='POST')
with urllib.request.urlopen(req,timeout=15) as r:
    if not 200 <= r.status < 300: raise SystemExit(f'POST failed: HTTP {r.status}')
PY
